mapper.select:
select d.PD_Name as pdName, d.P_Id as pId,
from SYS_Position_P p left join SYS_Department_P d on p.PD_ID=d.PD_ID left join SYS_Position_User_P pup on pup.PP_ID=p.PP_ID where pup.U_Id=#{uId}
and d.P_Id=#{pId}

select d.PD_Name as pdName,
from SYS_Position_P p left join SYS_Department_P d on p.PD_ID=d.PD_ID
order by p.${sortFiled} ${sortType}
order by p.PP_Sort asc
limit #{start},#{size}

sql.where:
1=1

    and p.PP_Code not in
    
        #{code}
    


    and p.PP_Status=#{ppStatus}


    and p.PD_ID=#{pdId}


    and d.PD_Code = #{pdCode}


    and p.PP_Name like concat('%',#{ppName},'%')


    and d.P_ID = #{pId}

mapper.select:
select d.PD_Id as pdId, d.PD_Code as pdCode, p.PP_ID as ppId, p.PP_Name as ppName, p.PP_Code as ppCode, d.PD_Name as pdName from SYS_Position_P p left join SYS_Department_P d on p.PD_ID=d.PD_ID WHERE d.P_ID=#{pId} and p.PP_Status = '1' and d.PD_Status = '1' and d.pd_code in
#{pdCode}
order by d.PD_Sort, p.Pp_Sort asc
